import random
from collections import deque

def compute_girth(edges, n=21):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = float('inf')
    for s in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for w in adj[u]:
                if w == parent[u]:
                    continue
                if dist[w] == -1:
                    dist[w] = dist[u] + 1
                    parent[w] = u
                    q.append(w)
                elif w != parent[u]:
                    cycle_len = dist[u] + dist[w] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

def is_4_colorable(edges, n=21):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n
    order = sorted(range(n), key=lambda v: -len(adj[v]))

    def backtrack(idx):
        if idx == n:
            return True
        v = order[idx]
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(4):
            if c not in used:
                colors[v] = c
                if backtrack(idx + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

# Let's try a different base structure
# Use a "caterpillar" or a tree with longer distances

def try_build_multiple():
    n = 21

    best_edges = None
    best_count = 0

    for attempt in range(100):
        # Start with a random tree
        # First, create a random tree by connecting vertices one by one
        vertices = list(range(n))
        random.shuffle(vertices)

        edges = []
        for i in range(1, n):
            # Connect vertices[i] to a random earlier vertex
            j = random.randint(0, i-1)
            edges.append((vertices[i], vertices[j]))

        # Now try to add edges between far-apart vertices
        def get_distances(edges):
            adj = [[] for _ in range(n)]
            for u, v in edges:
                adj[u].append(v)
                adj[v].append(u)

            dists = [[float('inf')]*n for _ in range(n)]
            for s in range(n):
                dists[s][s] = 0
                q = deque([s])
                while q:
                    u = q.popleft()
                    for w in adj[u]:
                        if dists[s][w] == float('inf'):
                            dists[s][w] = dists[s][u] + 1
                            q.append(w)
            return dists

        dists = get_distances(edges)

        candidates = []
        for i in range(n):
            for j in range(i+1, n):
                if dists[i][j] >= 7:
                    candidates.append((i, j, dists[i][j]))

        random.shuffle(candidates)
        added = []

        for i, j, d in candidates:
            test_edges = edges + added + [(i, j)]
            g = compute_girth(test_edges)
            if g >= 8:
                added.append((i, j))
                if len(edges) + len(added) >= 27:
                    break

        final_edges = edges + added
        total = len(final_edges)

        if total >= 27 and is_4_colorable(final_edges):
            g = compute_girth(final_edges)
            if g >= 8:
                print(f"Found! Attempt {attempt}: {total} edges, girth {g}")
                return final_edges

        if total > best_count:
            best_count = total
            best_edges = final_edges
            print(f"Attempt {attempt}: {total} edges, girth {compute_girth(final_edges)}")

    return best_edges

result = try_build_multiple()
print(f"\nFinal result: {len(result) if result else 0} edges")
if result:
    print(f"Edges: {result}")
    print(f"Girth: {compute_girth(result)}")
    print(f"4-colorable: {is_4_colorable(result)}")
